rules:
default allow := false

allow if {
  input.source_auth.method
  input.source_auth.method != "failed"
}

default allow := false

jwt_claim_values(v) := [v] if is_string(v)

jwt_claim_values(v) := v if is_array(v)

allow if {
  input.source_auth.method == "jwt_bearer"
  some v in jwt_claim_values(input.source_auth.claims[{{claim}}])
  v in {{values}}
}

default allow := false

jwt_audiences contains a if {
  a := input.source_auth.claims.aud
  is_string(a)
}

jwt_audiences contains a if {
  is_array(input.source_auth.claims.aud)
  some a in input.source_auth.claims.aud
}

allow if {
  input.source_auth.method == "jwt_bearer"
  input.source_auth.claims.iss in {{issuers}}
  some a in jwt_audiences
  a in {{audiences}}
}

default allow := false

role_claim_values(v) := [v] if is_string(v)

role_claim_values(v) := v if is_array(v)

authenticated_caller if {
  input.source_auth.method
  input.source_auth.method != "failed"
}

allow if {
  input.source_auth.method == "jwt_bearer"
  some role in role_claim_values(input.source_auth.claims.role)
  role in {{admin_roles}}
  input.mcp.method == "tools/call"
}

allow if {
  authenticated_caller
  input.mcp.method == "tools/call"
  input.mcp.tool_name in {{safe_tools}}
}

allow if {
  authenticated_caller
  input.mcp.method != "tools/call"
}

default allow := false

allow if {
  input.agent.did
  input.agent.did_verified == true
  input.agent.trust_verification == true
}

default allow := false

allow if {
  input.extension_identity.verified == true
  input.extension_identity.did in {{dids}}
}

default allow := false

allow if input.gateway.direction != "outbound"

allow if {
  input.gateway.direction == "outbound"
  some destination in {{destinations}}
  startswith(concat("", [input.gateway.target_id, "/"]), concat("", [trim_suffix(destination, "/"), "/"]))
}

default allow := false

allow if {{mode}}in_access_window

in_access_window if {
  access_day
  access_minute >= {{start_time}}
  access_minute < {{end_time}}
}

in_access_window if {
  {{start_time}} > {{end_time}}
  access_day
  access_minute >= {{start_time}}
}

in_access_window if {
  {{start_time}} > {{end_time}}
  access_day
  access_minute < {{end_time}}
}

access_minute := (hour * 60) + minute if {
  [hour, minute, _] := time.clock([time.now_ns(), {{time_zone}}])
}

access_day if count({{days}}) == 0

access_day if time.weekday([time.now_ns(), {{time_zone}}]) in {{days}}

default allow := false

target_check_ids contains r.id if {
  some r in input.trust_check_results.target
}

target_checks_passed contains r.id if {
  some r in input.trust_check_results.target
  r.ok == true
}

allow if {
  count(target_check_ids) > 0
  count(target_check_ids - target_checks_passed) == 0
}

default allow := false

target_checks_passing contains r.id if {
  some r in input.trust_check_results.target
  r.ok == true
}

allow if count(target_checks_passing) >= {{min_passing}}

default allow := false

allow if {
  some prefix in {{prefixes}}
  startswith(input.http.path, prefix)
  not contains(input.http.path, "..")
  not contains(lower(input.http.path), "%2e")
  not contains(input.http.path, "\\")
  not contains(lower(input.http.path), "%5c")
}

default allow := false

allow if {
  input.source_auth.method == "jwt_bearer"
  input.source_auth.subject in {{subjects}}
}

default allow := false

tool_claim_values(v) := [v] if is_string(v)

tool_claim_values(v) := v if is_array(v)

allow if {
  some v in tool_claim_values(input.jwt[{{claim}}])
  v in {{values}}
}

default allow := false

allow if input.jwt.role == {{admin_role}}

deny_reason := "The caller's token has no role" if not input.jwt.role

deny_reason := sprintf("Role %v may not call this tool", [input.jwt.role]) if {
  input.jwt.role
  input.jwt.role != {{admin_role}}
}
